import { cc, getRawProps, type SinwanNode } from "sinwan/component";

import { cn } from "@/lib/utils";
import {
  DialogClose as DialogClosePrimitive,
  DialogContent as DialogContentPrimitive,
  DialogOverlay as DialogOverlayPrimitive,
  DialogRoot,
  DialogTrigger as DialogTriggerPrimitive,
} from "sinwan-ui-core/overlay";
import { UiPortal } from "sinwan-ui-core/core";
import { useDrawerDrag, type DrawerDirection } from "./useDrawer";

type DrawerProps = {
  children?: SinwanNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  direction?: DrawerDirection;
};

function Drawer(props: DrawerProps) {
  const { children, direction = "bottom", ...rest } = getRawProps(props);
  return (
    <DialogRoot {...rest}>
      <div data-drawer-direction={direction} class="contents">
        {children}
      </div>
    </DialogRoot>
  );
}

type DrawerTriggerProps = {
  children?: SinwanNode;
  class?: string;
  asChild?: boolean;
};

function DrawerTrigger(props: DrawerTriggerProps) {
  return <DialogTriggerPrimitive {...props} />;
}

type DrawerPortalProps = {
  children?: SinwanNode;
};

function DrawerPortal({ children }: DrawerPortalProps) {
  return <UiPortal>{children}</UiPortal>;
}

type DrawerCloseProps = {
  children?: SinwanNode;
  class?: string;
  asChild?: boolean;
};

function DrawerClose(props: DrawerCloseProps) {
  return <DialogClosePrimitive {...props} />;
}

type DrawerOverlayProps = {
  class?: string;
};

function DrawerOverlay({ class: className }: DrawerOverlayProps) {
  return (
    <DialogOverlayPrimitive
      class={cn(
        "fixed inset-0 z-50 bg-black/10 duration-200 supports-backdrop-filter:backdrop-blur-xs data-open:animate-in data-open:fade-in-0 data-closed:animate-out data-closed:fade-out-0 data-closed:!fill-mode-forwards",
        className,
      )}
    />
  );
}

const DRAWER_HANDLE_CLASSES: Record<DrawerDirection, string> = {
  bottom: "order-first w-full pt-4 pb-2",
  top: "order-last w-full pt-2 pb-4",
  left: "absolute inset-y-0 right-0 w-4",
  right: "absolute inset-y-0 left-0 w-4",
};

const DRAWER_HANDLE_BAR_CLASSES: Record<DrawerDirection, string> = {
  bottom: "h-1 w-[100px]",
  top: "h-1 w-[100px]",
  left: "h-[100px] w-1",
  right: "h-[100px] w-1",
};

type DrawerHandleProps = {
  direction: DrawerDirection;
};

const DrawerHandle = cc<DrawerHandleProps>((props) => {
  const direction = props.direction;
  const { isDragging, onPointerDown } = useDrawerDrag(direction);
  return (
    <div
      data-slot="drawer-handle"
      data-dragging={() => (isDragging.value ? "true" : "false")}
      aria-hidden="true"
      class={cn(
        "group/drawer-handle flex shrink-0 cursor-grab touch-none items-center justify-center select-none data-[dragging=true]:cursor-grabbing",
        DRAWER_HANDLE_CLASSES[direction],
      )}
      onpointerdown={onPointerDown}
    >
      <div
        class={cn(
          "rounded-full bg-foreground/20 transition-colors group-hover/drawer-handle:bg-foreground/30 group-data-[dragging=true]/drawer-handle:bg-foreground/40",
          DRAWER_HANDLE_BAR_CLASSES[direction],
        )}
      />
    </div>
  );
});

type DrawerContentProps = {
  children?: SinwanNode;
  class?: string;
  direction?: DrawerDirection;
  showHandle?: boolean;
};

function DrawerContent({
  class: className,
  children,
  direction = "bottom",
  showHandle = true,
}: DrawerContentProps) {
  return (
    <>
      <DrawerOverlay />
      <DialogContentPrimitive
        data-slot="drawer-content"
        data-vaul-drawer-direction={direction}
        class={cn(
          "group/drawer-content fixed z-50 flex h-auto flex-col overflow-hidden rounded-xl bg-popover text-sm text-popover-foreground shadow-lg ring-1 ring-foreground/10 duration-200 data-[vaul-drawer-direction=bottom]:inset-x-4 data-[vaul-drawer-direction=bottom]:bottom-4 data-[vaul-drawer-direction=bottom]:mt-24 data-[vaul-drawer-direction=bottom]:max-h-[80vh] data-[vaul-drawer-direction=left]:inset-y-4 data-[vaul-drawer-direction=left]:left-4 data-[vaul-drawer-direction=left]:w-3/4 data-[vaul-drawer-direction=right]:inset-y-4 data-[vaul-drawer-direction=right]:right-4 data-[vaul-drawer-direction=right]:w-3/4 data-[vaul-drawer-direction=top]:inset-x-4 data-[vaul-drawer-direction=top]:top-4 data-[vaul-drawer-direction=top]:mb-24 data-[vaul-drawer-direction=top]:max-h-[80vh] data-[vaul-drawer-direction=left]:sm:max-w-sm data-[vaul-drawer-direction=right]:sm:max-w-sm data-open:animate-in data-open:fade-in-0 data-[vaul-drawer-direction=bottom]:data-open:slide-in-from-bottom-10 data-[vaul-drawer-direction=left]:data-open:slide-in-from-left-10 data-[vaul-drawer-direction=right]:data-open:slide-in-from-right-10 data-[vaul-drawer-direction=top]:data-open:slide-in-from-top-10 data-closed:animate-out data-closed:fade-out-0 data-closed:!fill-mode-forwards data-[vaul-drawer-direction=bottom]:data-closed:slide-out-to-bottom-10 data-[vaul-drawer-direction=left]:data-closed:slide-out-to-left-10 data-[vaul-drawer-direction=right]:data-closed:slide-out-to-right-10 data-[vaul-drawer-direction=top]:data-closed:slide-out-to-top-10",
          className,
        )}
      >
        {showHandle ? <DrawerHandle direction={direction} /> : null}
        {children}
      </DialogContentPrimitive>
    </>
  );
}

type DivProps = {
  children?: SinwanNode;
  class?: string;
};

function DrawerHeader({ class: className, ...props }: DivProps) {
  return (
    <div
      data-slot="drawer-header"
      class={cn(
        "flex flex-col gap-0.5 p-4 group-data-[vaul-drawer-direction=bottom]/drawer-content:text-center group-data-[vaul-drawer-direction=top]/drawer-content:text-center md:gap-0.5 md:text-left",
        className,
      )}
      {...props}
    />
  );
}

function DrawerFooter({ class: className, ...props }: DivProps) {
  return (
    <div
      data-slot="drawer-footer"
      class={cn("mt-auto flex flex-col gap-2 p-4", className)}
      {...props}
    />
  );
}

function DrawerTitle({ class: className, children, ...props }: DivProps) {
  return (
    <h2
      data-slot="drawer-title"
      class={cn(
        "font-heading text-base font-medium text-foreground",
        className,
      )}
      {...props}
    >
      {children}
    </h2>
  );
}

function DrawerDescription({
  class: className,
  children,
  ...props
}: DivProps) {
  return (
    <p
      data-slot="drawer-description"
      class={cn("text-sm text-muted-foreground", className)}
      {...props}
    >
      {children}
    </p>
  );
}

export {
  Drawer,
  DrawerClose,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerOverlay,
  DrawerPortal,
  DrawerTitle,
  DrawerTrigger,
};

export {
  Drawer,
  DrawerClose,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerOverlay,
  DrawerPortal,
  DrawerTitle,
  DrawerTrigger,
} from "./drawer";
export {
  useDrawerDrag,
  type DrawerDirection,
  type DrawerDragReturn,
} from "./useDrawer";

import { inject, onUnmounted } from "sinwan/component";
import { signal, type Signal } from "sinwan/reactivity";
import { DialogKey } from "sinwan-ui-core/overlay";

export type DrawerDirection = "top" | "bottom" | "left" | "right";

export type DrawerDragReturn = {
  isDragging: Signal<boolean>;
  onPointerDown: (event: PointerEvent) => void;
};

type DragAxis = {
  axis: "x" | "y";
  /** +1 when closing moves toward larger client coordinates. */
  sign: 1 | -1;
};

const DRAG_AXES: Record<DrawerDirection, DragAxis> = {
  bottom: { axis: "y", sign: 1 },
  top: { axis: "y", sign: -1 },
  right: { axis: "x", sign: 1 },
  left: { axis: "x", sign: -1 },
};

const CLOSE_DISTANCE_RATIO = 0.25;
const CLOSE_VELOCITY_PX_PER_MS = 0.4;
const VELOCITY_WINDOW_MS = 100;
const SNAP_BACK_MS = 200;
const SNAP_BACK_EASE = "cubic-bezier(0.32, 0.72, 0, 1)";

function resistedDistance(distance: number): number {
  if (distance >= 0) return distance;
  return -Math.sqrt(-distance) * 2;
}

function translate(axis: DragAxis["axis"], px: number): string {
  return axis === "x"
    ? `translate3d(${px}px, 0, 0)`
    : `translate3d(0, ${px}px, 0)`;
}

/**
 * Pointer drag on a drawer handle. Follows the pointer toward the drawer's
 * edge, closes past a quarter of the panel or on a flick, and otherwise
 * snaps back. A drag close points the exit animation off-screen so it
 * continues from the release position.
 */
export function useDrawerDrag(direction: DrawerDirection): DrawerDragReturn {
  const dialog = inject(DialogKey);
  if (!dialog) {
    throw new Error("useDrawerDrag must be used within a <Drawer />");
  }
  const { axis, sign } = DRAG_AXES[direction];
  const isDragging = signal(false);
  let stopDrag: (() => void) | null = null;
  let snapTimer: number | undefined;

  const clearSnapTimer = () => {
    if (snapTimer !== undefined) {
      window.clearTimeout(snapTimer);
      snapTimer = undefined;
    }
  };

  const clientAxis = (event: PointerEvent) =>
    axis === "x" ? event.clientX : event.clientY;

  const onPointerDown = (event: PointerEvent) => {
    if (event.button !== 0) return;
    const handle = event.currentTarget;
    const panel =
      handle instanceof Element
        ? handle.closest<HTMLElement>('[data-slot="drawer-content"]')
        : null;
    if (!panel) return;

    stopDrag?.();
    clearSnapTimer();
    const rect = panel.getBoundingClientRect();
    const size = axis === "x" ? rect.width : rect.height;
    const start = clientAxis(event);
    let distance = 0;
    let lastPos = start;
    let lastTime = performance.now();
    let velocity = 0;

    const finish = (commit: boolean) => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onCancel);
      isDragging.value = false;
      stopDrag = null;

      const recent = performance.now() - lastTime <= VELOCITY_WINDOW_MS;
      const flicked = recent && velocity >= CLOSE_VELOCITY_PX_PER_MS;
      const shouldClose =
        commit &&
        distance > 0 &&
        (distance >= size * CLOSE_DISTANCE_RATIO || flicked);
      if (shouldClose) {
        const offscreen = `max(100%, ${distance}px) + 1rem`;
        panel.style.setProperty(
          `--tw-exit-translate-${axis}`,
          sign > 0 ? `calc(${offscreen})` : `calc(-1 * (${offscreen}))`,
        );
        dialog.setOpen(false);
        return;
      }

      panel.style.transition = `transform ${SNAP_BACK_MS}ms ${SNAP_BACK_EASE}`;
      panel.style.transform = "";
      snapTimer = window.setTimeout(() => {
        snapTimer = undefined;
        panel.style.transition = "";
      }, SNAP_BACK_MS);
    };

    const onMove = (moveEvent: PointerEvent) => {
      if (moveEvent.cancelable) moveEvent.preventDefault();
      const pos = clientAxis(moveEvent);
      const now = performance.now();
      if (now > lastTime) velocity = ((pos - lastPos) * sign) / (now - lastTime);
      lastPos = pos;
      lastTime = now;
      distance = (pos - start) * sign;
      panel.style.transform = translate(axis, resistedDistance(distance) * sign);
    };

    const onUp = () => finish(true);
    const onCancel = () => finish(false);

    stopDrag = () => finish(false);
    isDragging.value = true;
    panel.style.transition = "none";
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onCancel);
  };

  onUnmounted(() => {
    stopDrag?.();
    clearSnapTimer();
  });

  return { isDragging, onPointerDown };
}
